<?php
namespace CloudHost247\Ovh\Services;
final class ProvisioningStatePresenter{private$states=array('pending'=>'Order recorded and waiting for OVH processing.','provisioning'=>'Your service is being prepared.','ordering'=>'A provisioning order is being prepared.','awaiting_order'=>'Waiting for an OVH order reference.','awaiting_confirmation'=>'Waiting for provider confirmation.','polling'=>'Checking the provider for completion.','active'=>'The service is active.','failed'=>'Provisioning could not complete. Support has been notified.','reconciliation_required'=>'The provider result must be safely reconciled before continuing.','intervention_required'=>'An administrator must review this service before continuing.','terminating'=>'Termination is in progress.','terminated'=>'The service has been terminated.');public function present($state,$isAdmin=false){$key=strtolower((string)$state);$known=isset($this->states[$key]);return array('key'=>$known?$key:'not_verified','label'=>$known?ucwords(str_replace('_',' ',$key)):'Not Verified','message'=>$known?$this->states[$key]:'The current provider state has not been verified.','diagnostic_visible'=>(bool)$isAdmin);}}
